#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Issue #209: Sign-in Providers configured from the Back Office (Connexion section,
# /admin/connexion). The code is deployed by CI and env's Google client is seeded as a
# provider by the migration; only a human can register the OAuth apps in Microsoft's,
# Apple's (and an OIDC issuer's) consoles and paste their credentials in the Back Office.
# Nothing is written to .env or GitHub: every value goes into the Connexion form, where it
# is encrypted (Provider Secrets, ADR-0020). Do it on staging first, then production, each
# with its own credentials. Never paste a secret in a ticket, a chat or a commit.

TOTAL_STAGES=6

banner "Sign-in Providers: Google, Microsoft, Apple and OIDC in the Back Office (#209)"

stage "Which app are you configuring?"
say "Every provider console needs this app's address in its redirect (callback) URLs."
ask TARGET_APP_URL "App address (e.g. https://staging.jobbbox.fr):"
TARGET_APP_URL="${TARGET_APP_URL%/}"
say "Callback URLs to paste in the consoles below:"
note "  Google:    $TARGET_APP_URL/api/auth/callback/google"
note "  Microsoft: $TARGET_APP_URL/api/auth/callback/microsoft"
note "  Apple:     $TARGET_APP_URL/api/auth/callback/apple"
note "  OIDC:      $TARGET_APP_URL/api/auth/callback/<the id you choose>"
note "The Connexion section shows each provider's exact URL too."
pause

stage "Google: check it still works after the deployment"
open_url "$TARGET_APP_URL/admin/connexion"
step "Sign in as a super-admin. Back office → Plateforme → Connexion."
say "Expected: a Google provider, Activé, its Secret client from \"environnement (repli)\"."
step "In a private window, open $TARGET_APP_URL/connexion → Continuer avec Google: you land on Mon compte."
note "Optional: Modifier Google → paste the client secret to store it encrypted; env's then stops being used."
if ! confirm "Does Google sign-in work?"; then
  SKIPPED+=("Google sign-in after deploy: check the web app log for [sign-in-providers] lines")
  warn "Check the web app log for [sign-in-providers] lines before going on."
fi
pause

stage "Microsoft: register an app in Microsoft Entra ID"
open_url "https://entra.microsoft.com/#view/Microsoft_AAD_RegisteredApps/ApplicationsListBlade"
step "App registrations → New registration. Name: Jobbbox (staging or production)."
step "Supported account types: \"Personal Microsoft accounts only\" (tenant consumers),"
step "  or your organisation only for a team sign-in (tenant = your tenant ID)."
step "Redirect URI: platform Web, $TARGET_APP_URL/api/auth/callback/microsoft → Register."
step "Overview: copy the Application (client) ID."
step "Certificates & secrets → New client secret → copy its Value (shown once)."
warn "Avoid tenant \"common\": any directory's admin can set any email, so its accounts are never linked by email."
note "Then in Connexion → Ajouter Microsoft: paste both, set Locataire, uncheck Activé, Enregistrer,"
note "click \"Tester la connexion avec Microsoft\", then Modifier → tick Activé → Enregistrer."
pause "Press Enter once Microsoft is added and tested (or to skip it)."

stage "Apple: a Services ID and a Sign in with Apple key"
warn "Apple refuses localhost: do this for staging or production only (paid Apple Developer account)."
open_url "https://developer.apple.com/account/resources/identifiers/list/serviceId"
step "Identifiers → + → Services IDs → identifier e.g. fr.jobbbox.web (this is the client ID)."
step "Enable Sign in with Apple → Configure: primary App ID, domain ${TARGET_APP_URL#https://},"
step "  return URL $TARGET_APP_URL/api/auth/callback/apple → Save."
step "Keys → + → enable Sign in with Apple → Configure with the same App ID → Register."
step "Download the .p8 key (only once) and note its Key ID; Membership details shows your Team ID."
note "Then in Connexion → Ajouter Apple: Service ID, Team ID, Key ID, paste the .p8 file's content."
note "Saving signs the client secret at once and shows the next signature date; the worker signs it again monthly."
note "Test it, then enable it. Keep the .p8 in the team's password manager, nowhere else."
pause "Press Enter once Apple is added and tested (or to skip it)."

stage "Generic OIDC (optional): a team or partner identity provider"
say "Any OpenID Connect issuer works (Okta, Keycloak, Authentik, Google Workspace via OIDC…)."
step "In the issuer's console, create a web (confidential) client with scopes openid email profile."
step "Redirect URI: $TARGET_APP_URL/api/auth/callback/<id>, the id you will type in Connexion (e.g. jobbbox-sso)."
step "Copy the client ID, the client secret and the discovery URL (…/.well-known/openid-configuration)."
step "Connexion → Ajouter OIDC: fill them in; tick \"Associer automatiquement…\" only if the issuer verifies emails."
step "Choose \"Proposer aux candidats\" and/or \"Autoriser pour la connexion au back office\", test, then enable."
pause "Press Enter once done (or to skip it)."

stage "Require SSO for Administrators (optional, off by default)"
say "Turn it on only once a provider allowed for Administrators works for every Administrator."
say "ADMIN_EMAILS super-admins are never asked, so you cannot lock yourself out."
open_url "$TARGET_APP_URL/admin/connexion"
step "Each Administrator links the provider once from Mon compte (or signs in with it)."
step "Connexion → Connexion de l'équipe → tick \"Exiger un fournisseur de connexion…\" → Enregistrer."
step "Check: an Administrator signed in by magic link opening /admin is asked to sign in with the provider."
pause

finish
